sysrule_view.script:
(function overrideView(view, is_list) {
    if (is_list) {
        answer = null;
        return;
    } // forms only; leave list views alone

    var P = 'x_2206627_er_tri_0.';
    if (gs.hasRole(P + 'triage_nurse')) { // also covers charge_nurse and app admin
        answer = 'nurse_review';
    } else if (gs.hasRole(P + 'provider')) {
        answer = 'provider_review';
    } else if (gs.hasRole(P + 'clinical_governance')) {
        answer = 'governance_audit';
    } else {
        answer = null; // fall back to the default view
    }
})(view, is_list);
